mapper.select:
WITH shape AS ( SELECT ST_GeomFromEWKB(decode(#{geometryHex}, 'hex')) AS geom ), source AS ( SELECT geom, ST_Length(geom) AS length_m FROM shape ), distances(seq_no, distance_m) AS ( VALUES
(CAST(#{index} AS integer) + 1, CAST(#{distance} AS double precision))
), points AS ( SELECT d.seq_no, d.distance_m, ST_Transform( CASE WHEN d.seq_no = 1 THEN ST_StartPoint(s.geom) WHEN d.seq_no = (SELECT MAX(seq_no) FROM distances) THEN ST_EndPoint(s.geom) ELSE ST_LineInterpolatePoint(s.geom, d.distance_m / s.length_m) END, 4326 ) AS geom FROM source s CROSS JOIN distances d ) SELECT seq_no, distance_m, ST_X(geom) AS longitude, ST_Y(geom) AS latitude FROM points ORDER BY seq_no

SELECT course_id
FROM public.course
WHERE course_id = #{courseId}
AND owner_user_id = #{ownerUserId}
AND del_yn = 'N'
FOR SHARE
